// Effective omission behavior is maintained independently of schema-level defaults.
export function omission(name, field) {
 const specific = {
  write_script: { language: 'required on create; ignored on update', content: 'required on create; unchanged on update', dedicated: 'create false; update unchanged', dedicated_count: 'create 2; update unchanged' },
  call_endpoint: { timeout_ms: '10000; max 60000', body: 'no request body', headers: 'no extra headers' },
  test_run_script: { timeout_ms: '30000; clamp 1000..60000', args: '{}', run_async: 'false', record: 'false' },
  list_recent_runs: { limit: '20; max 200' }, read_logs: { line_limit: '500; max 2000' },
  read_audit: { limit: '100; clamp 1..500' }, read_schedule_runs: { limit: '20; clamp 1..200' },
  list_files: { limit: '100; API clamp 1..1000' }, preview_cron: { count: '5; API clamp 1..20', timezone: 'deployment timezone (UTC default)' },
  publish_apply: { acknowledge_warnings: 'false', acknowledge_test_failures: 'false' },
  upsert_schedule: { inputs: '{}', enabled: 'true', on_overlap: 'skip', queue_cap: 'null', max_attempts: '1', retry_backoff_secs: '60', catch_up: 'true', timezone: 'deployment timezone (UTC default)' },
  upsert_alert: { enabled: 'true', window_secs: 'null; conditional' },
  create_endpoint: { tree: 'only tree, otherwise required', parent_id: 'tree root', proxy_strip_prefix: 'true', override_authorizers: 'false', authz_gates: 'inherit', allowed_authorizers: 'inherit' },
  move_endpoint: { parent_id: 'tree root (MOVE)' },
  update_endpoint_auth: { allowed_authorizers: 'preserve current', override_authorizers: 'preserve current', authz_gates: 'preserve current', inherit_authz_gates: 'false' },
  update_endpoint_info: { segment: 'unchanged', method: 'unchanged', script_name: 'unchanged', workflow_name: 'unchanged', overrides: 'unchanged', ws_config: 'unchanged', crud_config: 'unchanged', path_override: 'unchanged' }
 };
 if (field === 'project') return 'VIAT_PROJECT / current_project; else project_required';
 return specific[name]?.[field] ?? null;
}

function append(name, section, en, zh) {
 notes[name][section] = pair(notes[name][section].en + '\n\n' + en, notes[name][section]['zh-cn'] + '\n\n' + zh);
}
append('write_script', 'semantics',
 'Accepted language literals are `python`, `sql`, `typescript`, `shell`, `graphql`, `viat_gql`, `llm`, `rust`, `binary`. An unknown value is rejected by the API. Rust authoring can be disabled by the deployment’s `VIAT_RUST_AUTHORING` policy; Rust compilation is native code execution, not a security sandbox. A binary script’s content must be a valid manifest, not executable bytes; MCP has no artifact-upload tool (see [binary scripts](../assets/scripts/binary.md)). Script creation validates name length 1..64 bytes and forbids `/`; use a separate folder. New scripts default to `dedicated:false`, `dedicated_count:2`. Omitted flags on update preserve their current values; do not assume the default is one slot.',
 '支持的语言字面值为 `python`、`sql`、`typescript`、`shell`、`graphql`、`viat_gql`、`llm`、`rust`、`binary`，未知值被 API 拒绝。部署可通过 `VIAT_RUST_AUTHORING` 策略禁用 Rust 编写；Rust 编译会执行原生代码，不是安全沙箱。binary 正文必须是有效 manifest，不是可执行字节；MCP 无制品上传工具，参阅 [二进制脚本](../assets/scripts/binary.md)。创建名称长度须为 1..64 字节且不能含 `/`，文件夹另传。新脚本默认 `dedicated:false`、`dedicated_count:2`；更新省略时保留现值，不要假定默认只有一个槽。');
append('write_workflow', 'semantics',
 'Creation validates name length 1..64 bytes and forbids `/`. A byte-identical definition does not mint a new version. MCP uses `folder` both to locate and echo the selected folder, so this tool is not a general move-to-another-folder interface.',
 '创建名称长度须为 1..64 字节且不能含 `/`。定义字节完全相同不会创建新版本。MCP 用同一个 `folder` 定位并回传所选文件夹，因此本工具不是通用跨文件夹移动接口。');
append('create_endpoint', 'semantics',
 'A segment must be 1..64 bytes, cannot be bare `:`, and cannot contain `/` or whitespace. A WebSocket node may omit method (the API supplies GET); if a method is supplied it must be GET. In `ws_config.routes`, `script_id` wins over `script` if both are present. Route names are `[a-z0-9_]{1,64}` or `$connect`, `$disconnect`, `$default`; at least one message route other than connect/disconnect is required. `route_key` must be nonblank and at most 64 bytes, and quota values must be positive.',
 'segment 须为 1..64 字节，不能只有 `:`，不能含 `/` 或空白。WebSocket 可省略 method（API 设为 GET），提供时必须为 GET。`ws_config.routes` 同时提供 `script_id` 和 `script` 时 ID 优先。路由名为 `[a-z0-9_]{1,64}` 或 `$connect`、`$disconnect`、`$default`；至少有一个非 connect/disconnect 的消息路由。`route_key` 不能为空白且最多 64 字节，quota 数值必须为正。');
append('upsert_schedule', 'semantics',
 'A once schedule automatically disables after firing. Replacing an already-fired once schedule with the SAME instant does not re-arm it even if `enabled:true`; a new instant is a new occurrence. Inspect the echoed enabled state rather than assuming the requested flag won.',
 'once 计划触发后自动禁用。已触发 once 用同一时刻替换时，即使 `enabled:true` 也不会重新启用；新时刻才是新一次触发。应检查返回 enabled，不能假定请求标志一定胜出。');
append('upsert_alert', 'semantics',
 'The rule name must not be blank. SMTP configuration is required at SAVE time for an email rule, even when disabled, and recipients are validated as addresses. WeCom accounts are refused for unprompted alert messages; use a webhook or supported Feishu/Lark/DingTalk account instead. WeChat can be saved but delivery depends on a recipient’s recent-message permit. Push save validates the resource reference/kind and fixes its qualified folder choice; it does not validate provider credentials or prove handset delivery.',
 '规则名不能全为空白。email 规则即使禁用，保存时也必须配置 SMTP，并验证收件地址。WeCom 账号无法接收此类主动告警，会被拒绝；可改用 webhook 或支持的 Feishu/Lark/DingTalk 账号。WeChat 允许保存，但投递取决于接收者近期消息所授予的发送许可。push 保存会验证资源引用和类型，并固定限定文件夹，但不验证提供方凭据或证明手机收到。');
append('publish_apply', 'output',
 'In the pinned API, each endpoint entry has string UUID `id`, nullable string `method`, string `path`, UUID string `snapshot_id`, integer `snapshot_version`. Each build has string `script`, `language`, boolean `ok`, nullable string `error`, integer `duration_ms`, and optional `diagnostics` array (empty array omitted). Rust diagnostics contain strings `level`, `message`, `rendered`; optional strings `code`, `source`, `path`; optional unsigned integers `line`, `column` (omitted when absent). A build `ok:false` is result data and must be inspected even if the tool call succeeded.',
 '固定 API 中每个端点项含 UUID 字符串 `id`，可为 null 的字符串 `method`，字符串 `path`，UUID 字符串 `snapshot_id`，整数 `snapshot_version`。每个构建项含字符串 `script`、`language`，布尔值 `ok`，可为 null 的字符串 `error`，整数 `duration_ms`，可选 `diagnostics` 数组（空数组省略）。Rust 诊断含字符串 `level`、`message`、`rendered`，可选字符串 `code`、`source`、`path`，可选无符号整数 `line`、`column`（缺失时省略）。构建 `ok:false` 是结果数据，即使工具调用成功也要检查。');
append('publish_rollback', 'output',
 'In the pinned API, each endpoint entry has UUID string `id`, nullable string `method`, string `path`, nullable UUID string `restored_snapshot_id` and nullable integer `restored_snapshot_version`. These nullable keys remain present because the entries pass through unchanged; null can mean the endpoint had no prior snapshot to restore.',
 '固定 API 中每个端点项含 UUID 字符串 `id`，可为 null 的字符串 `method`，字符串 `path`，可为 null 的 UUID 字符串 `restored_snapshot_id` 和整数 `restored_snapshot_version`。这些键原样透传并保留 null；null 可能表示该端点之前没有可恢复快照。');
